  @Post(':id/root-cause')
  @HttpCode(200)
  @Action('annotate')
  @Audit({ action: 'DASH_ALERT_ANNOTATE', entity: 'dashboard.alert' })
  async rootCause(
    @Req() req: RequestLike,
    @Param('id') id: string,
    @Body() body: unknown,
    @Headers('if-match') ifMatch: string | string[] | undefined,
    @Res({ passthrough: true }) res: ResponseLike,
  ): Promise<Record<string, unknown>> {
